use std::sync::{Arc, Mutex};
use std::thread;

fn shared_counter() -> i32 {
    let counter = ⟦slot1⟧::new(Mutex::new(0));
    let mut handles = vec![];

    for _ in 0..5 {
        let c = ⟦slot2⟧::clone(&counter);
        handles.push(thread::spawn(move || {
            let mut guard = c.lock().unwrap();
            *guard += 1;
        }));
    }

    for h in handles {
        h.join().unwrap();
    }

    let guard = counter.lock().unwrap();
    *guard
}

fn main() {
    println!("{}", shared_counter());
}
